import { useNavigate } from 'react-router-dom';
import { LinkedMethods } from '../components/auth/LinkedMethods';
import { useAuth } from '../hooks/useAuth';

/**
 * Settings page for managing account preferences.
 * Protected route - redirects to login if not authenticated.
 */
export function Settings() {
  const { isAuthenticated, isLoading } = useAuth();
  const navigate = useNavigate();

  // Redirect if not authenticated
  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      navigate('/');
    }
  }, [isAuthenticated, isLoading, navigate]);

  // Show loading state while checking authentication
  if (isLoading) {
    return (
      <div className="settings-container">
        <div className="loading">Loading...</div>
      </div>
    );
  }

  // Don't render if not authenticated (redirect is in progress)
  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="settings-container">
      <header className="settings-header">
        <h1>Settings</h1>
        <button onClick={() => navigate('/dashboard')} className="back-button">
          Back to Dashboard
        </button>
      </header>
      <main className="settings-main">
        <section className="settings-section">
          <LinkedMethods />
        </section>
      </main>
    </div>
  );
}

import { type Page, type Locator } from '@playwright/test';

/**
 * Page object for Breadcrumbs component interactions.
 *
 * Encapsulates breadcrumb navigation for folder paths.
 * Uses semantic selectors for maintainability.
 */
export class BreadcrumbsPage {
  constructor(private readonly page: Page) {}

  /**
   * Get the breadcrumbs container.
   */
  container(): Locator {
    return this.page.locator('.breadcrumbs');
  }

  /**
   * Get all breadcrumb items.
   */
  breadcrumbItems(): Locator {
    return this.page.locator('.breadcrumb-item');
  }

  /**
   * Get a specific breadcrumb by name.
   */
  getBreadcrumb(name: string): Locator {
    return this.page.locator('.breadcrumb-item', { hasText: name });
  }

  /**
   * Get the home breadcrumb (root).
   */
  getHomeBreadcrumb(): Locator {
    return this.page.locator('.breadcrumb-item').first();
  }

  /**
   * Click a breadcrumb to navigate to that folder.
   */
  async clickBreadcrumb(name: string): Promise<void> {
    await this.getBreadcrumb(name).click();
  }

  /**
   * Click the home breadcrumb to navigate to root.
   */
  async clickHome(): Promise<void> {
    await this.getHomeBreadcrumb().click();
  }

  /**
   * Check if the breadcrumbs component is visible.
   */
  async isVisible(): Promise<boolean> {
    return await this.container().isVisible();
  }

  /**
   * Get the current path as array of breadcrumb names.
   * Returns folder names from root to current location.
   */
  async getCurrentPath(): Promise<string[]> {
    const items = this.breadcrumbItems();
    const count = await items.count();
    const path: string[] = [];

    for (let i = 0; i < count; i++) {
      const text = await items.nth(i).textContent();
      if (text) {
        // Clean up text (remove separators, trim)
        const cleaned = text.replace(/[/›>]/g, '').trim();
        if (cleaned) {
          path.push(cleaned);
        }
      }
    }

    return path;
  }

  /**
   * Get the number of breadcrumb items.
   * Root folder has 1 breadcrumb, nested folders have more.
   */
  async getBreadcrumbCount(): Promise<number> {
    return await this.breadcrumbItems().count();
  }

  /**
   * Get the last (current) breadcrumb text.
   */
  async getCurrentBreadcrumb(): Promise<string> {
    const items = this.breadcrumbItems();
    const count = await items.count();
    if (count === 0) {
      return '';
    }
    const text = await items.nth(count - 1).textContent();
    return text?.trim() ?? '';
  }

  /**
   * Check if a breadcrumb is clickable (not the current/last item).
   * The last breadcrumb is typically non-clickable.
   */
  async isBreadcrumbClickable(name: string): Promise<boolean> {
    const breadcrumb = this.getBreadcrumb(name);
    const isDisabled = await breadcrumb.getAttribute('aria-disabled');
    return isDisabled !== 'true';
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  HttpCode,
  HttpStatus,
  UseGuards,
  Request,
  Res,
  Req,
  UnauthorizedException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { Response, Request as ExpressRequest } from 'express';
import { AuthService } from './auth.service';
import { LoginDto, LoginResponseDto } from './dto/login.dto';
import { TokenResponseDto, LogoutResponseDto } from './dto/token.dto';
import {
  LinkMethodDto,
  AuthMethodResponseDto,
  UnlinkMethodDto,
  UnlinkMethodResponseDto,
} from './dto/link-method.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { User } from './entities/user.entity';

interface RequestWithUser extends Request {
  user: User;
}

// Cookie configuration
const REFRESH_TOKEN_COOKIE_OPTIONS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'lax' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  path: '/auth', // Only sent to auth endpoints
};

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
  @ApiResponse({
    status: 200,
    description: 'Successfully authenticated',
    type: LoginResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
  async login(
    @Body() loginDto: LoginDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<LoginResponseDto> {
    const result = await this.authService.login(loginDto);

    // Set refresh token in HTTP-only cookie
    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);

    // Return only accessToken and isNewUser (refreshToken goes in cookie)
    return {
      accessToken: result.accessToken,
      isNewUser: result.isNewUser,
    };
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
  @ApiResponse({
    status: 200,
    description: 'Tokens refreshed successfully',
    type: TokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
  async refresh(
    @Req() req: ExpressRequest,
    @Res({ passthrough: true }) res: Response
  ): Promise<TokenResponseDto> {
    const refreshToken = req.cookies?.['refresh_token'];
    if (!refreshToken) {
      throw new UnauthorizedException('No refresh token');
    }

    const result = await this.authService.refreshByToken(refreshToken);

    // Set new refresh token in HTTP-only cookie (rotation)
    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);

    // Return only accessToken (new refreshToken goes in cookie)
    return {
      accessToken: result.accessToken,
    };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Logout user and invalidate all refresh tokens' })
  @ApiResponse({
    status: 200,
    description: 'Successfully logged out',
    type: LogoutResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async logout(
    @Request() req: RequestWithUser,
    @Res({ passthrough: true }) res: Response
  ): Promise<LogoutResponseDto> {
    // Clear the refresh token cookie
    res.clearCookie('refresh_token', { path: '/auth' });

    return this.authService.logout(req.user.id);
  }

  @Get('methods')
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get all linked auth methods for the current user' })
  @ApiResponse({
    status: 200,
    description: 'List of linked auth methods',
    type: [AuthMethodResponseDto],
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getMethods(@Request() req: RequestWithUser): Promise<AuthMethodResponseDto[]> {
    return this.authService.getLinkedMethods(req.user.id);
  }

  @Post('link')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Link a new auth method to the current user account' })
  @ApiResponse({
    status: 200,
    description: 'Auth method linked successfully, returns updated list of methods',
    type: [AuthMethodResponseDto],
  })
  @ApiResponse({ status: 400, description: 'Auth method already linked or publicKey mismatch' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async linkMethod(
    @Request() req: RequestWithUser,
    @Body() linkDto: LinkMethodDto
  ): Promise<AuthMethodResponseDto[]> {
    return this.authService.linkMethod(req.user.id, linkDto);
  }

  @Post('unlink')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Unlink an auth method from the current user account' })
  @ApiResponse({
    status: 200,
    description: 'Auth method unlinked successfully',
    type: UnlinkMethodResponseDto,
  })
  @ApiResponse({ status: 400, description: 'Cannot unlink last auth method or method not found' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async unlinkMethod(
    @Request() req: RequestWithUser,
    @Body() unlinkDto: UnlinkMethodDto
  ): Promise<UnlinkMethodResponseDto> {
    await this.authService.unlinkMethod(req.user.id, unlinkDto.methodId);
    return { success: true };
  }
}

import { ApiProperty } from '@nestjs/swagger';

export class LinkMethodDto {
  @ApiProperty({ description: 'Web3Auth ID token from the new auth method' })
  idToken!: string;

  @ApiProperty({ description: 'Login type', enum: ['social', 'external_wallet'] })
  loginType!: 'social' | 'external_wallet';
}

export class AuthMethodResponseDto {
  @ApiProperty()
  id!: string;

  @ApiProperty({ enum: ['google', 'apple', 'github', 'email_passwordless', 'external_wallet'] })
  type!: string;

  @ApiProperty({ description: 'Email or wallet address' })
  identifier!: string;

  @ApiProperty({ nullable: true, type: Date })
  lastUsedAt!: Date | null;

  @ApiProperty()
  createdAt!: Date;
}

export class UnlinkMethodDto {
  @ApiProperty()
  methodId!: string;
}

export class UnlinkMethodResponseDto {
  @ApiProperty()
  success!: boolean;
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { authApi, AuthMethod } from '../lib/api/auth';

export function useLinkedMethods() {
  const queryClient = useQueryClient();

  const {
    data: methods = [],
    isLoading,
    error,
  } = useQuery<AuthMethod[], Error>({
    queryKey: ['auth-methods'],
    queryFn: authApi.getMethods,
  });

  const linkMutation = useMutation({
    mutationFn: authApi.linkMethod,
    onSuccess: (updatedMethods) => {
      // Update cache with the returned list
      queryClient.setQueryData(['auth-methods'], updatedMethods);
    },
  });

  const unlinkMutation = useMutation({
    mutationFn: authApi.unlinkMethod,
    onSuccess: () => {
      // Invalidate to refetch the updated list
      queryClient.invalidateQueries({ queryKey: ['auth-methods'] });
    },
  });

  return {
    methods,
    isLoading,
    error,
    linkMethod: linkMutation.mutateAsync,
    unlinkMethod: unlinkMutation.mutateAsync,
    isLinking: linkMutation.isPending,
    isUnlinking: unlinkMutation.isPending,
    linkError: linkMutation.error,
    unlinkError: unlinkMutation.error,
  };
}

