 51→  const { disconnect } = useDisconnect();
 52→
 53→  const isLastMethod = methods.length <= 1;
 54→
 55→  // Derive which method types are not yet linked (for showing "Link" buttons)
 56→  const linkedTypes = new Set(methods.map((m: AuthMethod) => m.type));
 57→  const availableMethods: Array<'google' | 'email' | 'wallet'> = [];
 58→  if (!linkedTypes.has('google')) availableMethods.push('google');
 59→  if (!linkedTypes.has('email')) availableMethods.push('email');
 60→  // Multiple wallets allowed -- wallet is always available
 61→  availableMethods.push('wallet');
 62→
 63→  const clearLinking = useCallback(() => {
 64→    setLinkingType(null);
 65→    setActionError(null);
 66→  }, []);
