 70→      setActionError(null);
 71→      try {
 72→        // Get CipherBox identity JWT from Google token (link intent skips user creation)
 73→        const identity = await authApi.identityGoogle(googleIdToken, 'link');
 74→        // Link with the CipherBox JWT
 75→        await linkMethod({
