 77→          loginType: 'google',
 78→        });
 79→        clearLinking();
 80→      } catch (err) {
 81→        const message = extractErrorMessage(err, 'Failed to link Google account');
 82→        setActionError(message);
 83→      }
 84→    },
 85→    [linkMethod, clearLinking]
