382→function extractErrorMessage(err: unknown, fallback: string): string {
383→  if (err instanceof Error) {
384→    // Axios-style error with response data
385→    const axiosErr = err as { response?: { data?: { message?: string } } };
386→    if (axiosErr.response?.data?.message) {
387→      return axiosErr.response.data.message;
388→    }
389→    return err.message;
390→  }
391→  return fallback;
